"""Enumerate the exact Seidel spectrum of K_{m,n} and of K_{m,n} minus one
cross edge, and compare against a numerical eigenvalue solver."""
from __future__ import annotations
import math
from typing import List
import numpy as np


def seidel_matrix_Kmn(m: int, n: int) -> np.ndarray:
    v = m + n
    S = np.zeros((v, v))
    for i in range(v):
        for j in range(v):
            if i != j:
                same = (i < m) == (j < m)
                S[i, j] = 1.0 if same else -1.0
    return S


def predicted_base_spectrum(m: int, n: int) -> List[float]:
    N = m + n
    return sorted([-1.0] * (N - 1) + [float(N - 1)])


def predicted_deleted_spectrum(m: int, n: int) -> List[float]:
    N = m + n
    disc = math.sqrt((N - 2) * (N + 6))
    return sorted([-1.0] * (N - 3) + [1.0,
                  ((N - 4) + disc) / 2, ((N - 4) - disc) / 2])


def demo(m: int, n: int) -> None:
    S = seidel_matrix_Kmn(m, n)
    base = sorted(np.round(np.linalg.eigvalsh(S), 6).tolist())
    Sdel = S.copy(); Sdel[0, m] = 1.0; Sdel[m, 0] = 1.0
    deleted = sorted(np.round(np.linalg.eigvalsh(Sdel), 6).tolist())
    print(f"K_{{{m},{n}}} base    : {base}")
    print(f"        predicted: {[round(x,6) for x in predicted_base_spectrum(m,n)]}")
    print(f"K_{{{m},{n}}} deleted : {deleted}")
    print(f"        predicted: {[round(x,6) for x in predicted_deleted_spectrum(m,n)]}")


if __name__ == "__main__":
    for (m, n) in [(2, 2), (3, 3), (2, 15)]:
        demo(m, n)

"""Sweep (m, n) and confirm the sharp threshold: the Seidel energy strictly
increases under a single edge deletion iff m + n >= 4."""
from __future__ import annotations
import math


def energy_base(m: int, n: int) -> float:
    return 2.0 * (m + n - 1)


def energy_deleted(m: int, n: int) -> float:
    N = m + n
    return (N - 2) + math.sqrt((N - 2) * (N + 6))


def sweep(max_sum: int = 12) -> None:
    print(f"{'m':>3}{'n':>3}{'E(base)':>12}{'E(del)':>12}{'inc?':>6}{'m+n>=4':>8}")
    for m in range(1, max_sum):
        for n in range(1, max_sum):
            if m + n < 3 or m + n > max_sum:
                continue
            eb, ed = energy_base(m, n), energy_deleted(m, n)
            inc = ed > eb + 1e-12
            pred = (m + n) >= 4
            assert inc == pred, f"threshold mismatch at ({m},{n})"
            print(f"{m:>3}{n:>3}{eb:>12.4f}{ed:>12.4f}{str(inc):>6}{str(pred):>8}")
    print("Threshold m+n>=4 verified over the sweep.")


if __name__ == "__main__":
    sweep()

"""Compute the exact energy gap E(K_{m,n}-e) - E(K_{m,n}) and show it is an
increasing function of N = m + n that crosses zero exactly at N = 3."""
from __future__ import annotations
import math


def energy_gap(m: int, n: int) -> float:
    N = m + n
    return ((N - 2) + math.sqrt((N - 2) * (N + 6))) - 2.0 * (N - 1)


def gap_by_total(N: int) -> float:
    # depends only on N = m + n
    return (N - 2) + math.sqrt((N - 2) * (N + 6)) - 2 * (N - 1)


if __name__ == "__main__":
    print(f"{'N=m+n':>6}{'gap':>14}")
    for N in range(3, 20):
        g = gap_by_total(N)
        print(f"{N:>6}{g:>14.6f}")
    print()
    print(f"gap at N=3 : {gap_by_total(3):.6f}  (zero: boundary)")
    print(f"gap at N=4 : {gap_by_total(4):.6f}  (positive: strict increase)")

