from __future__ import annotations


def seidel_energy_complete_bipartite(m: int, n: int) -> float:
    """Exact Seidel energy of K_{m,n} in O(1).

    The Seidel matrix is S = w w^T - I with w in {+1,-1}^{m+n}; its spectrum is
    {m+n-1} together with -1 of multiplicity m+n-1, giving energy 2(m+n-1).
    """
    if m + n < 1:
        raise ValueError("need m + n >= 1")
    return 2.0 * (m + n - 1)

